import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/TypeScriptHandbook.html","title":"TypeScriptHandbook","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":4.35,"words":1305},"filePathRelative":"TypeScriptHandbook.md"}`),a={name:`TypeScriptHandbook.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="typescripthandbook" tabindex="-1"><a class="header-anchor" href="#typescripthandbook"><span>TypeScriptHandbook</span></a></h1><p><a href="./TypeScript.html">TypeScript</a>の公式サイトのドキュメント。Bookといいつつ本じゃない。</p><p><a href="https://www.typescriptlang.org/docs/handbook/intro.html" target="_blank" rel="noopener noreferrer">TypeScript: Handbook - The TypeScript Handbook</a></p><p>読んで思った事を適当に書く。新しいのは上に足します。</p><h2 id="classに対するtypeof" tabindex="-1"><a class="header-anchor" href="#classに対するtypeof"><span>classに対するtypeof</span></a></h2><p><a href="https://www.typescriptlang.org/docs/handbook/2/classes.html#abstract-construct-signatures" target="_blank" rel="noopener noreferrer">Classes#Abstract Construct Signatures</a> の所で、以下のようなコードがあった。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">function</span> <span class="token function">greet</span><span class="token punctuation">(</span>ctor<span class="token operator">:</span> <span class="token keyword">typeof</span> Base<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> instance <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ctor</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Cannot create an instance of an abstract class.</span></span>
<span class="line">  instance<span class="token punctuation">.</span><span class="token function">printName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>エラーになるのはabstract classだからだ、という話だが、それ以前にtypeof Baseの所が何をやっているか戸惑ったのでメモ。</p><p>JavaScriptは、expressionでtypeofを使う事が出来るが、TypeScriptはさらにこれをtypeコンテキストでも使えるように拡張している。</p><p><a href="https://www.typescriptlang.org/docs/handbook/2/typeof-types.html#the-typeof-type-operator" target="_blank" rel="noopener noreferrer">Typeof Type Operator</a></p><p>そしてtypeコンテキストではtypeofは変数やプロパティの型を返す、とある。</p><p>上記のBaseはclass宣言で作られるものだが、これはコンストラクタの入った変数名でもある。そのためtypeof ClassNameでそのコンストラクタの型が返る事になる。 ただコンストラクタはnewで使うとそのオブジェクトを返す、という特殊な型であるので、単なる関数の型では無く、newで呼べて、この時はインスタンスの型を返す、という特殊なsignatureになると思われる。</p><p>たぶん<a href="https://www.typescriptlang.org/docs/handbook/2/functions.html#construct-signatures" target="_blank" rel="noopener noreferrer">More on Functions#Construct Signatures</a>に書いてある、 以下のSomeConstructorみたいな感じの型になるんじゃないか。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">type</span> <span class="token class-name">SomeConstructor</span> <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">new</span> <span class="token punctuation">(</span>s<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span><span class="token operator">:</span> SomeObject<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">fn</span><span class="token punctuation">(</span>ctor<span class="token operator">:</span> SomeConstructor<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">ctor</span><span class="token punctuation">(</span><span class="token string">&quot;hello&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>JavaScriptのtypeofのつもりで読んでいると&quot;function&quot;が返るんじゃないの？という気分になってしまうので、型コンテキストだというのを注意する必要がある。</p><h2 id="keyofをstringに限定する理由" tabindex="-1"><a class="header-anchor" href="#keyofをstringに限定する理由"><span>keyofをstringに限定する理由</span></a></h2><p><a href="https://www.typescriptlang.org/docs/handbook/2/template-literal-types.html" target="_blank" rel="noopener noreferrer">Template Literal Types</a>で以下のようなコードがあった。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">type</span> <span class="token class-name">PropEventSource<span class="token operator">&lt;</span>Type<span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">on</span><span class="token punctuation">(</span>eventName<span class="token operator">:</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token builtin">string</span> <span class="token operator">&amp;</span> <span class="token keyword">keyof</span> Type<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">Changed</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">,</span> <span class="token function-variable function">callback</span><span class="token operator">:</span> <span class="token punctuation">(</span>newValue<span class="token operator">:</span> <span class="token builtin">any</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">void</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token keyword">void</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>なんで <code>string &amp;</code>がいるんだろう？とchatGPTに聞いたら、keyofはindexとかの数字も入る、 とのこと。ただしこのkeyofを見るのはなかなか難しい。</p><p>以下はうまくいった。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">type</span> <span class="token class-name">hoge</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token boolean">false</span><span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> <span class="token class-name">a</span> <span class="token operator">=</span> <span class="token keyword">keyof</span> hoge</span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> <span class="token class-name">Debug</span> <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token constant">P</span> <span class="token keyword">in</span> a<span class="token punctuation">]</span><span class="token operator">:</span> <span class="token constant">P</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Debugにホバーすると一通り出る。</p><h2 id="conditional-type" tabindex="-1"><a class="header-anchor" href="#conditional-type"><span>Conditional Type</span></a></h2><p>こんなのあるんだ、という感じ。</p><p><a href="https://www.typescriptlang.org/docs/handbook/2/conditional-types.html" target="_blank" rel="noopener noreferrer">Conditional Types</a></p><p>述語にはextendsを使うのが読みにくさを感じるが、constraintsと同じものと思えばそういうものか。</p><p>引数の型をつけるにはGenericsを使うが、返る型は全然関係ないのが返るのが不思議な感じはするな。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">interface</span> <span class="token class-name">IdLabel</span> <span class="token punctuation">{</span></span>
<span class="line">  id<span class="token operator">:</span> <span class="token builtin">number</span> <span class="token comment">/* some fields */</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">interface</span> <span class="token class-name">NameLabel</span> <span class="token punctuation">{</span></span>
<span class="line">  name<span class="token operator">:</span> <span class="token builtin">string</span> <span class="token comment">/* other fields */</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> <span class="token class-name">NameOrId<span class="token operator">&lt;</span><span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token builtin">number</span> <span class="token operator">|</span> <span class="token builtin">string</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token class-name"><span class="token builtin">number</span></span></span>
<span class="line">  <span class="token operator">?</span> IdLabel</span>
<span class="line">  <span class="token operator">:</span> NameLabel<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>この時、<code>NameOrId&lt;T&gt;</code>型はIdLabelとかNameLabelを返すのであって、NameOrId型は返さない。 単なる関数のようなものとしてGenericsが使われるのがちょっと違和感があったのでメモしておく。</p><h3 id="inferキーワード" tabindex="-1"><a class="header-anchor" href="#inferキーワード"><span>inferキーワード</span></a></h3><p>後で見た時になんだったか忘れて見直すハメになったのでメモしておく。</p><p>Conditional Typeで以下のような文があったとする。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">type</span> <span class="token class-name">Flatten<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token class-name"><span class="token builtin">any</span></span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">?</span> <span class="token constant">T</span><span class="token punctuation">[</span><span class="token builtin">number</span><span class="token punctuation">]</span> <span class="token operator">:</span> <span class="token constant">T</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Conditional Typeを使って何らかの制約を課して、それが満たされている時に型を取り出す、みたいな処理。 これと同じような事を以下のようにinferキーワードを使って書ける。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">type</span> <span class="token class-name">Flatten<span class="token operator">&lt;</span>Type<span class="token operator">&gt;</span></span> <span class="token operator">=</span> Type <span class="token keyword">extends</span> <span class="token class-name"><span class="token builtin">Array</span><span class="token operator">&lt;</span><span class="token keyword">infer</span> Item<span class="token operator">&gt;</span></span> <span class="token operator">?</span> Item <span class="token operator">:</span> Type<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Itemというのが新しく導入される訳だ。</p><h2 id="generics-2026-08-06-木" tabindex="-1"><a class="header-anchor" href="#generics-2026-08-06-木"><span>Generics 2026-08-06 (木)</span></a></h2><p><a href="https://www.typescriptlang.org/docs/handbook/2/generics.html" target="_blank" rel="noopener noreferrer">Generics</a></p><h3 id="タイプパラメータがinterface側に無いものが書ける" tabindex="-1"><a class="header-anchor" href="#タイプパラメータがinterface側に無いものが書ける"><span>タイプパラメータがinterface側に無いものが書ける</span></a></h3><p>interfaceにタイプパラメータが無いのもOK。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">interface</span> <span class="token class-name">GenericIdentityFn</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token operator">&lt;</span>Type<span class="token operator">&gt;</span><span class="token punctuation">(</span>arg<span class="token operator">:</span> Type<span class="token punctuation">)</span><span class="token operator">:</span> Type<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>これはcall signatureの例で関数として呼べる、という奴だ。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">function identity&lt;Type&gt;(arg: Type): Type {</span>
<span class="line">  return arg;</span>
<span class="line">}</span>
<span class="line"> </span>
<span class="line">let myIdentity: GenericIdentityFn = identity;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ただここで言いたいのはそれよりも、GenericIdentityFnの方にはタイプパラメータが無い、という所。</p><p>ちなみに以下のようにも書けて、</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">interface</span> <span class="token class-name">GenericIdentityFn<span class="token operator">&lt;</span>Type<span class="token operator">&gt;</span></span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token punctuation">(</span>arg<span class="token operator">:</span> Type<span class="token punctuation">)</span><span class="token operator">:</span> Type<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>この場合使う時に指定がいるらしい。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">let</span> myIdentity<span class="token operator">:</span> GenericIdentityFn<span class="token operator">&lt;</span><span class="token builtin">number</span><span class="token operator">&gt;</span> <span class="token operator">=</span> identity<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>なんかinferされても良さそうなもんだが。</p><h3 id="keyofの引数" tabindex="-1"><a class="header-anchor" href="#keyofの引数"><span>keyofの引数</span></a></h3><p>以下みたいな例があった。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">function</span> <span class="token generic-function"><span class="token function">getProperty</span><span class="token generic class-name"><span class="token operator">&lt;</span>Type<span class="token punctuation">,</span> Key <span class="token keyword">extends</span> <span class="token keyword">keyof</span> Type<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span>obj<span class="token operator">:</span> Type<span class="token punctuation">,</span> key<span class="token operator">:</span> Key<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> obj<span class="token punctuation">[</span>key<span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"> </span>
<span class="line"><span class="token keyword">let</span> x <span class="token operator">=</span> <span class="token punctuation">{</span> a<span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> b<span class="token operator">:</span> <span class="token number">2</span><span class="token punctuation">,</span> c<span class="token operator">:</span> <span class="token number">3</span><span class="token punctuation">,</span> d<span class="token operator">:</span> <span class="token number">4</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>以下のように、キーとして存在しない文字列はNGとなる。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token function">getProperty</span><span class="token punctuation">(</span>x<span class="token punctuation">,</span> <span class="token string">&quot;a&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token function">getProperty</span><span class="token punctuation">(</span>x<span class="token punctuation">,</span> <span class="token string">&quot;m&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// NG</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>という事はリテラル型しか使えないという事かな？ 以下のように書くと、kはanyとなるので使う事が出来てしまう。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">function</span> <span class="token function">hoge</span><span class="token punctuation">(</span>k<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token function">getProperty</span><span class="token punctuation">(</span>x<span class="token punctuation">,</span> k<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token function">hoge</span><span class="token punctuation">(</span><span class="token string">&quot;ika&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token comment">// undefined</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>なお、kにstringのアノテーションをつけると <code>&quot;a&quot; | &quot;b&quot; | &quot;c&quot; | &quot;d&quot; </code> でない、と型チェックで弾かれる。 やはりリテラルでないと駄目らしい。</p><p>anyで抜けられるのはなるほど、という感じだな。</p><h2 id="intersection-type" tabindex="-1"><a class="header-anchor" href="#intersection-type"><span>Intersection Type</span></a></h2><p><a href="https://www.typescriptlang.org/docs/handbook/2/objects.html" target="_blank" rel="noopener noreferrer">Object Types</a></p><p>Object Typeにintersection typeの記述があり、はじめて触れるものなので少しメモ。</p><p>以下のようなのがそれ。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">interface</span> <span class="token class-name">Colorful</span> <span class="token punctuation">{</span></span>
<span class="line">  color<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">interface</span> <span class="token class-name">Circle</span> <span class="token punctuation">{</span></span>
<span class="line">  radius<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"> </span>
<span class="line"><span class="token keyword">type</span> <span class="token class-name">ColorfulCircle</span> <span class="token operator">=</span> Colorful <span class="token operator">&amp;</span> Circle<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ColorfulCircleは両方のメンバを持つ。集合的にはintersectionになっているので普通なんだが、 なんとなく一瞬共通のメンバしか持たないように感じるので注意が必要か。 型を構造体のように見るのでは無く値の方を集合論的感覚で見る必要があるよなぁ。</p><h2 id="more-on-function" tabindex="-1"><a class="header-anchor" href="#more-on-function"><span>More on Function</span></a></h2><p><a href="https://www.typescriptlang.org/docs/handbook/2/functions.html" target="_blank" rel="noopener noreferrer">More on Functions</a></p><p>ジェネリクスとかの話があるが、あんまり凄い意外な事が無いのでメモする事は少ない。</p><h3 id="ジェネリクスのconstraints" tabindex="-1"><a class="header-anchor" href="#ジェネリクスのconstraints"><span>ジェネリクスのconstraints</span></a></h3><p>extendsで書く。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">function</span> <span class="token generic-function"><span class="token function">longest</span><span class="token generic class-name"><span class="token operator">&lt;</span>Type <span class="token keyword">extends</span> <span class="token punctuation">{</span> length<span class="token operator">:</span> <span class="token builtin">number</span> <span class="token punctuation">}</span><span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span>a<span class="token operator">:</span> Type<span class="token punctuation">,</span> b<span class="token operator">:</span> Type<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>a<span class="token punctuation">.</span>length <span class="token operator">&gt;=</span> b<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> a<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> b<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>この辺のシンタックスはすぐ忘れるのでメモしておく。</p><h3 id="function-type-expressionとcall-signatureとコンストラクタ" tabindex="-1"><a class="header-anchor" href="#function-type-expressionとcall-signatureとコンストラクタ"><span>Function Type ExpressionとCall Signatureとコンストラクタ</span></a></h3><p>関数の型はarrow functionっぽいシンタックス（Function Type Expressionと言うらしい）で表せる。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token punctuation">(</span>a<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">void</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>ここで、aは省略出来ない。<code>(string)=&gt;void</code> はstringという名前のany引数だと解釈される（！？）</p><p>一方オブジェクトがcallableであるのは、Call Sinatureと言うらしく、なぜかアローじゃない。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">type</span> <span class="token class-name">DescribableFunction</span> <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  description<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">(</span>someArg<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">boolean</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>DescraibableFunction型の値は普通に呼べる。</p><p>なお、コンストラクタも似た感じに書ける。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">type</span> <span class="token class-name">SomeConstructor</span> <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">new</span> <span class="token punctuation">(</span>s<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span><span class="token operator">:</span> SomeObject<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>これはnewでSomeConstructor型を呼ぶケース。</p><h3 id="function-overloads" tabindex="-1"><a class="header-anchor" href="#function-overloads"><span>Function Overloads</span></a></h3><p>こんな機能あるんだ！？overloaded signatureだけ呼べて、implementation signatureの関数は呼べないとか。ほえ〜。</p><h2 id="narrowing" tabindex="-1"><a class="header-anchor" href="#narrowing"><span>Narrowing</span></a></h2><p><a href="https://www.typescriptlang.org/docs/handbook/2/narrowing.html" target="_blank" rel="noopener noreferrer">Narrowing</a></p><p>ここはなかなか面白いな。こういうのをちゃんと知りたかった。 最近の言語では標準装備という感じだけれど。Kotlinとかもこの辺は普通にあるよな。</p><h3 id="discriminated-union" tabindex="-1"><a class="header-anchor" href="#discriminated-union"><span>Discriminated Union</span></a></h3><p>後から見直す時にどこにあったか忘れがちなのでメモ。Narrowingに書いてある。</p><p>ちなみにinterfaceで定義してunionにしている例があるが、structurally typedなので単にanonymous objectとか渡せる、という話は<a href="https://www.typescriptlang.org/docs/handbook/2/everyday-types.html#interfaces" target="_blank" rel="noopener noreferrer">Everyday Types: Interfaces</a>に書いてある。</p><h3 id="type-predicates" tabindex="-1"><a class="header-anchor" href="#type-predicates"><span>Type predicates</span></a></h3><p><a href="https://www.typescriptlang.org/docs/handbook/2/narrowing.html#using-type-predicates" target="_blank" rel="noopener noreferrer">Narrowing: Using type predicates</a></p><p>user-defined type guard！こんなのあるんだ！へー。 以下のpet is Fishというreturn value。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">function</span> <span class="token function">isFish</span><span class="token punctuation">(</span>pet<span class="token operator">:</span> Fish <span class="token operator">|</span> Bird<span class="token punctuation">)</span><span class="token operator">:</span> pet <span class="token keyword">is</span> Fish <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">(</span>pet <span class="token keyword">as</span> Fish<span class="token punctuation">)</span><span class="token punctuation">.</span>swim <span class="token operator">!==</span> <span class="token keyword">undefined</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>JavaScript的にはbooleanだが引数に関する特別な処理な事を型のsignatureレベルで表現するのね。</p><h2 id="everyday-types-2026-08-04-火" tabindex="-1"><a class="header-anchor" href="#everyday-types-2026-08-04-火"><span>Everyday Types 2026-08-04 (火)</span></a></h2><p><a href="https://www.typescriptlang.org/docs/handbook/2/everyday-types.html" target="_blank" rel="noopener noreferrer">Everyday Types</a></p><h3 id="optional-chainの他の言語との違い" tabindex="-1"><a class="header-anchor" href="#optional-chainの他の言語との違い"><span>Optional Chainの他の言語との違い</span></a></h3><p>Optionalの意味がnullでは無くで存在しない、なのがちょっと注意が必要。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">function</span> <span class="token function">printName</span><span class="token punctuation">(</span>obj<span class="token operator">:</span> <span class="token punctuation">{</span> first<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span> last<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token comment">// ...</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>とあった時、lastが無い場合がある、というのがオプショナルの意味になる。 無意識にlastがnullかどうか、的な意味に思ってしまうが、そもそもlastが存在するかしないかなのでだいぶ意味合いが違う。</p><p>この辺はJavaScriptのoptional chainの話なので<a href="./JavaScript.html">JavaScript</a>の方に書いておくが、メソッド呼び出しやインデクサなどにドットがついたりするのが一見すると意外性があるが良く考えるともっともだ。</p><h3 id="union型とnarrow" tabindex="-1"><a class="header-anchor" href="#union型とnarrow"><span>Union型とnarrow</span></a></h3><p>見た目は<a href="./FSharp.html">FSharp</a>とかのDiscriminated Unionに似ているが、振る舞いとしてはgenericsのconstraintsが指定されたものに似ている。 共通のメソッドだけが呼べる、というような。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">function</span> <span class="token function">getFirstThree</span><span class="token punctuation">(</span>x<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">|</span> <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> x<span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>個々の型を取り出すのはnarrowingする、と書いてあって、以下みたいにisArrayとかでも出来るらしい。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">function</span> <span class="token function">welcomePeople</span><span class="token punctuation">(</span>x<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">|</span> <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token builtin">Array</span><span class="token punctuation">.</span><span class="token function">isArray</span><span class="token punctuation">(</span>x<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Here: &#39;x&#39; is &#39;string[]&#39;</span></span>
<span class="line">    <span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Hello, &quot;</span> <span class="token operator">+</span> x<span class="token punctuation">.</span><span class="token function">join</span><span class="token punctuation">(</span><span class="token string">&quot; and &quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Here: &#39;x&#39; is &#39;string&#39;</span></span>
<span class="line">    <span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Welcome lone traveler &quot;</span> <span class="token operator">+</span> x<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>型検査器はどうやってisArrayのセマンティクスを知っているのだろう？特別扱いしているのかな？</p><p><a href="https://www.typescriptlang.org/play/?#" target="_blank" rel="noopener noreferrer">TypeScript: TS Playground - An online editor for exploring TypeScript and JavaScript</a></p><p>少なくともMyIsArrayでくくるくらいでは動くようだ。でもreturn trueじゃ駄目なんだから伝播はするらしいな。</p><p><a href="https://www.typescriptlang.org/docs/handbook/typescript-in-5-minutes-func.html#unions" target="_blank" rel="noopener noreferrer">TypeScript for Functional Programmers</a> の方に、built-in predicatesが載っていて、ここにArray.isArrayは特別扱いしているな。</p><p>（追記: あとでtype predicatesというセクションでこの話がある、後述）</p><h3 id="type-aliases" tabindex="-1"><a class="header-anchor" href="#type-aliases"><span>Type Aliases</span></a></h3><p>type文は型を定義しているのではなく、aliasなんだな。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">type</span> <span class="token class-name">Point</span> <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  x<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span></span>
<span class="line">  y<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>これは、右辺だけで型になっていて、単にそれに名前がついているだけ。新しい型が出来る訳では無い。</p><p>structural typeと合わせると、typedefみたいに別の型にする事は出来ない、という事だな。</p><h3 id="interface" tabindex="-1"><a class="header-anchor" href="#interface"><span>interface</span></a></h3><p>typeと似ていて、ほとんど同じに使えるけれど、extendsしたりメソッド足したりが出来るのがinterfaceか。 メソッドを足していくのがdeclaration mergingと呼ぶらしい。C++のnamespaceとかこういう感じだよな。</p><p>集合論的に考えればtypeだけで全部済みそうな気もするが、 よりJavaとかのinterfaceっぽく差分だけで定義していけるのが便利なケースはあるかもしれない。</p><p>プロパティも普通にフィールドを定義して、classでフィールドを定義すればimplementsした事になる。 この辺はあくまでstructureが一致しているかをチェックするだけなのでスロットがあるかを気にする必要が無いTypeScriptならでは。</p><p><a href="https://www.typescriptlang.org/docs/handbook/2/classes.html#implements-clauses" target="_blank" rel="noopener noreferrer">Classes: implements Clauses</a> あたりにもその辺の話題がある。</p><h3 id="literal-type" tabindex="-1"><a class="header-anchor" href="#literal-type"><span>Literal Type</span></a></h3><p>文字列とかを型に入れているのはどういう仕組なんだろう？と思っていたが、Literal Typeという概念があるのか。 リテラルはそれぞれその値固有の型とみなされるのでunionとかに入れれるのね。</p><p>C++のTemplateがなんとなく値が入れられるのとは違って、こっちの方が型システム的にちゃんとしているな。</p><p>ただオブジェクトのプロパティとかのinferenceが絡むと結構分かりにくい挙動をするな。 以下の例がreq.methodがstringになるのでエラーになるのは結構意外だ。</p><p>確かにconstでもプロパティは変えられちゃうんだよな。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">declare</span> <span class="token keyword">function</span> <span class="token function">handleRequest</span><span class="token punctuation">(</span>url<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">,</span> method<span class="token operator">:</span> <span class="token string">&quot;GET&quot;</span> <span class="token operator">|</span> <span class="token string">&quot;POST&quot;</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token keyword">void</span><span class="token punctuation">;</span></span>
<span class="line"> </span>
<span class="line"><span class="token keyword">const</span> req <span class="token operator">=</span> <span class="token punctuation">{</span> url<span class="token operator">:</span> <span class="token string">&quot;https://example.com&quot;</span><span class="token punctuation">,</span> method<span class="token operator">:</span> <span class="token string">&quot;GET&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// NG</span></span>
<span class="line"><span class="token function">handleRequest</span><span class="token punctuation">(</span>req<span class="token punctuation">.</span>url<span class="token punctuation">,</span> req<span class="token punctuation">.</span>method<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>そしてas constなんてものもあるらしい。これをするとmethodもLiteral Typeになるとか。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> req <span class="token operator">=</span> <span class="token punctuation">{</span> url<span class="token operator">:</span> <span class="token string">&quot;https://example.com&quot;</span><span class="token punctuation">,</span> method<span class="token operator">:</span> <span class="token string">&quot;GET&quot;</span> <span class="token punctuation">}</span> <span class="token keyword">as</span> <span class="token keyword">const</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>これでreq.methodがstringじゃなくて&quot;GET&quot;型になるらしい。へー。</p><h2 id="basic-types-2026-08-04-火" tabindex="-1"><a class="header-anchor" href="#basic-types-2026-08-04-火"><span>Basic Types 2026-08-04 (火)</span></a></h2><p><a href="https://www.typescriptlang.org/docs/handbook/2/basic-types.html" target="_blank" rel="noopener noreferrer">The Basics</a></p><p>lenientは寛大な、という意味らしい。lenient typeでanyとかの一番ゆるい型を指す。 inference takes the most lenient types は推論がany側になる事でゆるい型チェックを実現している事を指している模様。</p><p>strictnessのオプションなど、tsc周辺の話の基本的な事が結構はいっているセクション。</p><h2 id="typescript-for-javascript-programmers-2026-08-04-火" tabindex="-1"><a class="header-anchor" href="#typescript-for-javascript-programmers-2026-08-04-火"><span>TypeScript for JavaScript Programmers 2026-08-04 (火)</span></a></h2><p><a href="https://www.typescriptlang.org/docs/handbook/typescript-in-5-minutes.html" target="_blank" rel="noopener noreferrer">TypeScript for JavaScript Programmers</a></p><p>これはハンドブックの一部じゃないかもしれないが、先に読んどけ、と言われたので読んでおく。 ちなみにJSの他にCSharpやFunctional Programmer向けのもあって、それぞれ特徴が良くでていて面白い。</p><p>Structural Typeは特徴的だな。</p>`,138)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};